import openpyxl

# Compare ALL cell values across all source sheets for variants A vs B
def all_values(wb):
    result = {}
    for sn in wb.sheetnames:
        ws = wb[sn]
        vals = {}
        for row in range(1, ws.max_row+1):
            for col in range(1, ws.max_column+1):
                v = ws.cell(row=row, column=col).value
                if v is not None:
                    vals[(row, col)] = v
        result[sn] = vals
    return result

wb_a = openpyxl.load_workbook('data/workbooks/working_paper_variant_a.xlsx', data_only=False)
wb_b = openpyxl.load_workbook('data/workbooks/working_paper_variant_b.xlsx', data_only=False)
wb_c = openpyxl.load_workbook('data/workbooks/working_paper_variant_c.xlsx', data_only=False)

va = all_values(wb_a)
vb = all_values(wb_b)
vc = all_values(wb_c)

# Compare A vs B
diffs_ab = []
for sn in ['lap-1', 'lap-2', 'lap-9']:
    all_keys = set(va[sn].keys()) | set(vb[sn].keys())
    for k in sorted(all_keys):
        a = va[sn].get(k)
        b = vb[sn].get(k)
        if a != b:
            diffs_ab.append((sn, k, a, b))

print(f"A vs B: {len(diffs_ab)} differences")
if diffs_ab:
    for d in diffs_ab[:10]:
        col_letter = openpyxl.utils.get_column_letter(d[1][1])
        print(f"  {d[0]} {col_letter}{d[1][0]}: {repr(d[2])} vs {repr(d[3])}")

# Compare A vs C
diffs_ac = []
for sn in ['lap-1', 'lap-2', 'lap-9']:
    all_keys = set(va[sn].keys()) | set(vc[sn].keys())
    for k in sorted(all_keys):
        a = va[sn].get(k)
        c = vc[sn].get(k)
        if a != c:
            diffs_ac.append((sn, k, a, c))

print(f"\nA vs C: {len(diffs_ac)} differences")
if diffs_ac:
